// Command cataloggen emits the static MCP catalog data used by the coverage
// drift gate. It is a one-shot development tool: it reads the current proto
// descriptors and RBAC mapping, then writes internal/mcp/catalog_data.go.
// Regenerating is a deliberate act; the drift test fails when a future change
// to the mounted surface or RBAC scopes is not reflected in the generated file.
package main

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"os"
	"sort"
	"strings"

	"github.com/athNdev/carbon-panel/internal/rbac"
	_ "github.com/athNdev/carbon-panel/pkg/proto/carbonpanel/v1"
	"google.golang.org/protobuf/reflect/protoreflect"
	"google.golang.org/protobuf/reflect/protoregistry"
)

// mountedServices mirrors the 25 mux.Handle registrations in
// internal/rpc/server.go registerServices. Keep in sync by hand; the drift
// test asserts this list is exactly the set of mounted services.
var mountedServices = []string{
	"AuthService", "ConfigService", "FileService", "MinecraftService", "ModService",
	"ModBrowseService", "ModpackService", "DatapackService", "ProxyService", "ServerService",
	"NodeService", "SupportService", "TaskService", "ActivityService", "OperationService",
	"SubuserService", "BlueprintService", "BackupService", "UserService", "RoleService",
	"ModuleService", "UploadService", "PlayerService", "WorldViewService", "WorldService",
}

func scopeKey(procedure string) string {
	if rbac.PublicProcedures[procedure] {
		return "public"
	}
	if rbac.AuthenticatedOnlyProcedures[procedure] {
		return "authenticated"
	}
	p, ok := rbac.ProcedurePermissions[procedure]
	if !ok {
		panic("procedure has no RBAC mapping: " + procedure)
	}
	if p.ObjectIDField != "" {
		return p.Resource + "/" + p.Action + "[" + p.ObjectIDField + "]"
	}
	return p.Resource + "/" + p.Action
}

func fieldsKey(m protoreflect.MessageDescriptor) string {
	var parts []string
	for i := 0; i < m.Fields().Len(); i++ {
		f := m.Fields().Get(i)
		typ := f.Kind().String()
		switch f.Kind() {
		case protoreflect.MessageKind, protoreflect.GroupKind:
			typ += ":" + string(f.Message().FullName())
		case protoreflect.EnumKind:
			typ += ":" + string(f.Enum().FullName())
		}
		parts = append(parts, fmt.Sprintf("%d:%s:%s:%s", f.Number(), f.Name(), f.Cardinality(), typ))
	}
	return strings.Join(parts, ";")
}

func buildForService(service string) string {
	switch service {
	case "PlayerService", "WorldService", "WorldViewService", "ModBrowseService":
		return "PanelBuildPostStable"
	default:
		return "PanelBuildStableV140"
	}
}

type entry struct {
	procedure string
	service   string
	method    string
	client    string
	scope     string
	build     string
}

func main() {
	var entries []entry
	var fingerprintParts []string
	for _, service := range mountedServices {
		fullName := protoreflect.FullName("carbonpanel.v1." + service)
		desc, err := protoregistry.GlobalFiles.FindDescriptorByName(fullName)
		if err != nil {
			panic(fmt.Sprintf("find %s: %v", fullName, err))
		}
		sd, ok := desc.(protoreflect.ServiceDescriptor)
		if !ok {
			panic(fmt.Sprintf("%s is not a service", fullName))
		}
		for i := 0; i < sd.Methods().Len(); i++ {
			md := sd.Methods().Get(i)
			procedure := "/" + string(sd.FullName()) + "/" + string(md.Name())
			entries = append(entries, entry{
				procedure: procedure,
				service:   string(fullName),
				method:    string(md.Name()),
				client:    "New" + service + "Client",
				scope:     scopeKey(procedure),
				build:     buildForService(service),
			})
			fingerprintParts = append(fingerprintParts, strings.Join([]string{
				procedure,
				string(md.Input().FullName()),
				string(md.Output().FullName()),
				fieldsKey(md.Input()),
				fieldsKey(md.Output()),
			}, "|"))
		}
	}
	sort.Slice(entries, func(i, j int) bool { return entries[i].procedure < entries[j].procedure })
	sort.Strings(fingerprintParts)
	sum := sha256.Sum256([]byte(strings.Join(fingerprintParts, "\n")))
	fingerprint := hex.EncodeToString(sum[:])

	var b strings.Builder
	b.WriteString("// Code generated by internal/mcp/cataloggen. DO NOT EDIT.\n")
	b.WriteString("// Source of truth: proto descriptors for the 25 mounted services in\n")
	b.WriteString("// internal/rpc/server.go registerServices, plus internal/rbac scopes.\n\n")
	b.WriteString("package mcp\n\n")
	b.WriteString("const descriptorFingerprint = \"" + fingerprint + "\"\n\n")
	b.WriteString("var rawCatalogEntries = []CatalogEntry{\n")
	for _, e := range entries {
		fmt.Fprintf(&b, "\t{Procedure: %q, Service: %q, Method: %q, Client: %q, Scope: %q, Class: ClassExclude, Build: %s},\n",
			e.procedure, e.service, e.method, e.client, e.scope, e.build)
	}
	b.WriteString("}\n")

	if err := os.WriteFile("internal/mcp/catalog_data.go", []byte(b.String()), 0o644); err != nil {
		panic(err)
	}
	fmt.Printf("entries=%d services=%d fingerprint=%s\n", len(entries), len(mountedServices), fingerprint)
}
